<section class="page-banner"><div class="container"><div class="section-label">MODERATION</div><h1>Review events</h1><p>Approve or decline submitted events before they become visible to students.</p></div></section><section class="section container"><?php require dirname(__DIR__).'/partials/admin_nav.php'; ?><div class="right-align"><a class="btn btn-primary" href="<?= e(url('admin/event/new')) ?>">+ Add event</a> <a class="btn btn-outline" href="<?= e(url('admin/club/form')) ?>">+ Add club</a></div><div class="filter-pills"><?php foreach(['pending'=>'Pending','approved'=>'Approved','rejected'=>'Rejected','cancelled'=>'Cancelled','completed'=>'Completed','all'=>'All'] as $key=>$label): ?><a class="filter-pill <?= $status===$key?'chosen':'' ?>" href="<?= e(url('admin/events',['status'=>$key])) ?>"><?= e($label) ?></a><?php endforeach; ?></div><div class="card panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Event</th><th>Club / organizer</th><th>Schedule</th><th>Bookings</th><th>Status</th><th>Review</th></tr></thead><tbody><?php foreach($events as $ev): ?><tr><td><strong><a href="<?= e(url('event',['id'=>$ev['id']])) ?>"><?= e($ev['title']) ?></a></strong><div class="small-muted"><?= e(short_text($ev['description'],90)) ?></div></td><td><?= e($ev['club_name']) ?><br><small><?= e($ev['organizer']) ?></small></td><td><?= e(pretty_date($ev['starts_at'])) ?><br><small><?= e($ev['venue']) ?></small><?php if($ev['registration_deadline']): ?><br><small>Deadline: <?= e(pretty_date($ev['registration_deadline'])) ?></small><?php endif; ?></td><td><?= (int)$ev['booked'] ?> / <?= (int)$ev['capacity'] ?></td><td><?= status_pill($ev['status']) ?></td><td><div class="row-actions"><?php if($ev['status']==='pending'): ?><form method="post" action="<?= e(url('admin/event/status')) ?>" class="form-stack"><?= csrf_field() ?><input type="hidden" name="event_id" value="<?= (int)$ev['id'] ?>"><label><span class="small-muted">Review note (optional)</span><input name="review_note" maxlength="1000" placeholder="Reason / requested change"></label><?php foreach(['approved'=>'Approve','rejected'=>'Reject'] as $change=>$label): ?><button name="status" value="<?= e($change) ?>" type="submit" class="btn <?= $change==='approved'?'btn-success':'btn-outline' ?> btn-sm"><?= e($label) ?></button><?php endforeach; ?></form><?php endif; ?><?php if($ev['review_note']): ?><small>Note: <?= e(short_text($ev['review_note'],140)) ?></small><?php endif; ?><?php if($ev['status']==='approved' && strtotime($ev['ends_at'])<=time()): ?><form method="post" action="<?= e(url('admin/event/status')) ?>"><?= csrf_field() ?><input type="hidden" name="event_id" value="<?= (int)$ev['id'] ?>"><button class="btn btn-success btn-sm" name="status" value="completed">Complete</button></form><?php endif; ?><?php if($ev['status']==='approved'): ?><form method="post" action="<?= e(url('admin/event/status')) ?>" data-confirm="Cancel this approved event?"><?= csrf_field() ?><input type="hidden" name="event_id" value="<?= (int)$ev['id'] ?>"><button name="status" value="cancelled" class="btn btn-danger-outline btn-sm" type="submit">Cancel</button></form><?php endif; ?></div></td></tr><?php endforeach; ?><?php if(!$events): ?><tr><td colspan="6">No events in this category.</td></tr><?php endif; ?></tbody></table></div></div></section>
